const useRenameCallbacks = ()=>{
    const perf = usePerformance();
    const trackProjectAction = useProjectActionAnalytics();
    const perfTracker = useRef();
    return useMemo(()=>{
        const renameEvent = (element, values)=>{
            trackProjectAction({
                element,
                subcategory: ProjectViewLocations.ProjectContents,
                pagename: 'rename',
                ...values
            });
        };
        const metricLogger = Metrics[AAVComponentId.PROJECTS]?.getOperationalMetricLogger(ActionAnalyticsValue.Rename);
        return {
            onCancel: (element)=>{
                renameEvent(element, {
                    type: 'click',
                    subtype: 'rename-cancel'
                });
                aav_rename_callbacks(metricLogger).onCancel(element);
            },
            onConfirm: (element)=>{
                perfTracker.current = {
                    finish: perf.startMeasure('RenameAsset')
                };
                renameEvent(element, {
                    type: 'click',
                    subtype: 'rename-confirm'
                });
                aav_rename_callbacks(metricLogger).onConfirm(element);
            },
            onConflict: (element)=>{
                renameEvent(element, {
                    type: 'click',
                    subtype: 'conflict'
                });
                aav_rename_callbacks(metricLogger).onConflict(element);
            },
            onError: (error, element)=>{
                renameEvent(element, {
                    type: 'error',
                    subtype: 'rename',
                    sequence: 'toast',
                    error
                });
                aav_rename_callbacks(metricLogger).onError(error, element);
            },
            onSuccess: (element)=>{
                perfTracker.current?.finish();
                renameEvent(element, {
                    type: 'success',
                    subtype: 'rename',
                    sequence: 'toast'
                });
                aav_rename_callbacks(metricLogger).onSuccess(element);
            }
        };
    }, [
        perf,
        trackProjectAction
    ]);
};
